import random
import base64
from datetime import datetime
from flask import Flask, render_template_string, redirect, url_for, request, jsonify

app = Flask(__name__)

# ==============================================================================
# BRAND ASSET — APAW logo, embedded as base64 so the app stays a single
# self-contained file with no static folder and no external asset requests.
# ==============================================================================
LOGO_B64 = ""

# ==============================================================================
# DEPLOYMENT NOTE — VERCEL / SERVERLESS VERSION
# ------------------------------------------------------------------------------
# Vercel runs this as a stateless serverless function: there is no long-lived
# background thread here (unlike the Raspberry Pi build), and in-memory
# globals can reset whenever a fresh instance spins up. So:
#   - Sensor readings are generated FRESH on every request instead of being
#     updated by a background loop — same visual effect, serverless-safe.
#   - SIMULATION_MODE and resident_reports are still plain globals. This is
#     fine for a live demo (Vercel keeps the function warm across the
#     back-to-back requests of one presentation), but don't rely on it for
#     a real multi-day deployment — swap in Vercel KV / a small DB for that.
#     The real field deployment target is the Pi build, not this one.
# ==============================================================================

SIMULATION_MODE = "normal"

NODE_META = {
    "inflow_a": {"label": "Inflow A", "desc": "Upstream Creek — Purok 1", "kind": "inflow", "x": 18, "y": 22},
    "inflow_b": {"label": "Inflow B", "desc": "Upstream Canal — Purok 3", "kind": "inflow", "x": 18, "y": 78},
    "inflow_c": {"label": "Inflow C", "desc": "Storm Drain — Access Rd.", "kind": "inflow", "x": 50, "y": 12},
    "outflow":  {"label": "Outflow",  "desc": "Main Drainage Exit",       "kind": "outflow", "x": 84, "y": 50},
}
NODE_ORDER = ["inflow_a", "inflow_b", "inflow_c", "outflow"]

resident_reports = []

def generate_reading():
    """Compute one node's snapshot on demand — no background thread needed."""
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    if SIMULATION_MODE == "normal":
        return {
            "risk_level": "Normal",
            "confidence": round(random.uniform(96, 99), 1),
            "water_level": round(random.uniform(0.3, 0.7), 2),
            "water_flow": round(random.uniform(1.0, 3.5), 2),
            "rainfall": 0.0,
            "temperature": round(random.uniform(28.0, 31.0), 1),
            "humidity": round(random.uniform(70.0, 80.0), 1),
            "timestamp": now
        }
    else:
        return {
            "risk_level": "Critical",
            "confidence": round(random.uniform(91, 96), 1),
            "water_level": round(random.uniform(2.8, 3.6), 2),
            "water_flow": round(random.uniform(12.0, 18.5), 2),
            "rainfall": round(random.uniform(35.0, 65.0), 1),
            "temperature": round(random.uniform(23.0, 25.5), 1),
            "humidity": round(random.uniform(92.0, 98.0), 1),
            "timestamp": now
        }

def current_status():
    return {node_id: generate_reading() for node_id in NODE_ORDER}

