# ==============================================================================
# WEB ROUTES
# ==============================================================================
import json as _json

@app.route('/')
def dashboard():
    status = current_status()
    return render_template_string(
        DASHBOARD_HTML,
        status=status,
        any_node=status["inflow_a"],
        meta=NODE_META,
        node_order=NODE_ORDER,
        reports=resident_reports,
        meta_json=_json.dumps(NODE_META)
    )

@app.route('/api/status')
def api_status():
    return jsonify({"status": current_status()})

@app.route('/resident')
def resident_portal():
    return render_template_string(RESIDENT_HTML, meta=NODE_META, node_order=NODE_ORDER)

@app.route('/controls')
def presenter_controls():
    return render_template_string(CONTROLS_HTML)

@app.route('/upload', methods=['POST'])
def upload_report():
    if 'photo' in request.files:
        file = request.files['photo']
        node = request.form.get('node', '')
        if file.filename != '':
            image_b64 = base64.b64encode(file.read()).decode('utf-8')
            report_id = len(resident_reports) + 1
            resident_reports.append({
                "id": report_id,
                "image_data": image_b64,
                "node": node,
                "time": datetime.now().strftime("%H:%M:%S"),
                "status": "Pending"
            })
    return redirect(url_for('resident_portal'))

@app.route('/verify/<int:report_id>')
def verify_report(report_id):
    for r in resident_reports:
        if r['id'] == report_id:
            r['status'] = "Verified"
    return redirect(url_for('dashboard'))

@app.route('/reject/<int:report_id>')
def reject_report(report_id):
    for r in resident_reports:
        if r['id'] == report_id:
            r['status'] = "Flagged"
    return redirect(url_for('dashboard'))

@app.route('/set_mode/<mode_type>')
def set_mode(mode_type):
    global SIMULATION_MODE
    if mode_type in ['normal', 'storm']: SIMULATION_MODE = mode_type
    return redirect(url_for('dashboard'))

# Local testing only — Vercel invokes `app` directly via its Python runtime
if __name__ == "__main__":
    app.run(host='0.0.0.0', port=5000, debug=False)